def eval_expression(expr):
    import re

    # Tokenize input into numbers, operators, and parentheses
    token_pattern = r'\d+|\+|-|\*|\/|\(|\)|\s'
    tokens = list(re.findall(token_pattern, expr))
    tokens = [t for t in tokens if t.strip()]  # Remove whitespace

    # Global position tracker
    pos = 0
    length = len(tokens)

    def parse_expression():
        """Handles + and - with lower precedence"""
        left = parse_term()
        while pos < length and tokens[pos] in ['+', '-']:
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if right == 0 and op == '/':
                raise ZeroDivisionError("division by zero")
            elif op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        """Handles * and / with higher precedence"""
        left = parse_factor()
        while pos < length and tokens[pos] in ['*', '/']:
            op = tokens[pos]
            pos += 1
            right = parse_factor()
            if right == 0:
                raise ZeroDivisionError("division by zero")
            elif op == '*':
                left = left * right
            else:
                left = left / right
        return left

    def parse_factor():
        """Handles numbers and parenthesized expressions"""
        if pos >= length:
            return 0

        token = tokens[pos]

        # Handle unary minus (before number or '(')
        if token == '-' and (pos == 0 or tokens[pos - 1] in ['(', '+', '-', '*', '/']):
            pos += 1
            value = parse_factor()
            return -value

        # Opening parenthesis
        if token == '(':
            pos += 1
            result = parse_expression()
            if pos < length and tokens[pos] == ')':
                pos += 1
            else:
                raise ValueError("Missing closing parenthesis")
            return result

        # Regular number
        elif token.isdigit():
            num = int(token)
            pos += 1
            return num

        else:
            raise ValueError(f"Unexpected token: {token}")

    try:
        result = parse_expression()

        # Check that all tokens were consumed
        if pos < length and tokens[pos].strip():
            raise ValueError("Unexpected extra tokens in expression")

        return result
    except ZeroDivisionError:
        raise
    except (ValueError, IndexError):
        raise

# Example usage
print(eval_expression("3 + 4 * (2 - 1)"))      # Output: 7
print(eval_expression("10 / 2"))               # Output: 5.0
print(eval_expression("-3 + 4 * 2"))           # Output: 5
print(eval_expression("(10 - 2) / 8 * -2"))    # Output: -2.0
try:
    print(eval_expression("5 / 0"))            # Raises ZeroDivisionError
except ZeroDivisionError as e:
    print(f"Caught error: {e}")                # Output: Caught error: division by zero
